struct aiScene
{
    unsigned int mFlags;
    C_STRUCT aiNode* mRootNode;
    unsigned int mNumMeshes;
    C_STRUCT aiMesh** mMeshes;
    unsigned int mNumMaterials;
    C_STRUCT aiMaterial** mMaterials;
    unsigned int mNumAnimations;
    C_STRUCT aiAnimation** mAnimations;
    unsigned int mNumTextures;
    C_STRUCT aiTexture** mTextures;
    unsigned int mNumLights;
    C_STRUCT aiLight** mLights;
    unsigned int mNumCameras;
    C_STRUCT aiCamera** mCameras;
    C_STRUCT aiMetadata* mMetaData;
    C_STRUCT aiString mName;
#ifdef __cplusplus
    ASSIMP_API aiScene();
    ASSIMP_API ~aiScene();
    inline bool HasMeshes() const { return mMeshes != nullptr && mNumMeshes > 0; }
    inline bool HasMaterials() const { return mMaterials != nullptr && mNumMaterials > 0; }
    inline bool HasLights() const { return mLights != nullptr && mNumLights > 0; }
    inline bool HasTextures() const { return mTextures != nullptr && mNumTextures > 0; }
    inline bool HasCameras() const { return mCameras != nullptr && mNumCameras > 0; }
    inline bool HasAnimations() const { return mAnimations != nullptr && mNumAnimations > 0; }
    static const char* GetShortFilename(const char* filename) {
        const char* lastSlash = strrchr(filename, '/');
        if (lastSlash == nullptr) {
            lastSlash = strrchr(filename, '\\');
        }
        const char* shortFilename = lastSlash != nullptr ? lastSlash + 1 : filename;
        return shortFilename;
    }
    const aiTexture* GetEmbeddedTexture(const char* filename) const {
        return GetEmbeddedTextureAndIndex(filename).first;
    }
    std::pair<const aiTexture*, int> GetEmbeddedTextureAndIndex(const char* filename) const {
        if (nullptr==filename) {
            return std::make_pair(nullptr, -1);
        }
        if ('*' == *filename) {
            int index = std::atoi(filename + 1);
            if (0 > index || mNumTextures <= static_cast<unsigned>(index)) {
                return std::make_pair(nullptr, -1);
            }
            return std::make_pair(mTextures[index], index);
        }
        const char* shortFilename = GetShortFilename(filename);
        if (nullptr == shortFilename) {
            return std::make_pair(nullptr, -1);
        }
        for (unsigned int i = 0; i < mNumTextures; i++) {
            const char* shortTextureFilename = GetShortFilename(mTextures[i]->mFilename.C_Str());
            if (strcmp(shortTextureFilename, shortFilename) == 0) {
                return std::make_pair(mTextures[i], i);
            }
        }
        return std::make_pair(nullptr, -1);
    }
#endif // __cplusplus
#ifdef __cplusplus
    void* mPrivate;
#else
    char* mPrivate;
#endif
};

